chk("210.5",  "הכנס לדני את הקוואקר 60 גרם לבוקר",              name="דני",   food="קוואקר",  grams="60",  meal="בוקר")
chk("210.6",  "הוסף לליצקו את הטונה 100 גרם לצהריים",           name="ליצקו", food="טונ",     grams="100", meal="צהריים")
chk("210.7",  "תוסיפי לרון את הגבינה 5% 40 גרם לבוקר",          name="רון",   food="גבינ",    grams="40",  meal="בוקר")
