# ═══════════════════════════════════════════════════════════════════════
# קבוצה 211: שכחת אות ראשונה — reduce verbs
# ═══════════════════════════════════════════════════════════════════════
print("\n══ קב׳ 211: שכחת אות ראשונה reduce ══")
chk("211.1",  "ורד לרון אורז 80 גרם",                           name="רון",   food="אורז",    grams="80")   # ורד≠הורד → no reduce
chk("211.2",  "פחת לדני פסטה 90 גרם",                           name="דני",   food="פסטה",    grams="90")   # פחת≠הפחת → no reduce
chk("211.3",  "וסף לליצקו חזה עוף 120 גרם",                     name="ליצקו", food="חזה עוף", grams="120")  # וסף≠הוסף → just name+food
chk("211.4",  "וריד לרון בטטה 80 גרם",                          name="רון",   food="בטטה",    grams="80")   # וריד≠הוריד → no reduce
chk("211.5",  "פחיתי לדני קוואקר 60 גרם",                       name="דני",   food="קוואקר",  grams="60")   # פחיתי≠הפחיתי
chk("211.6",  "תוריד לליצקו טונה 100 גרם",                      name="ליצקו", food="טונ",     grams="100", reduce=True)  # תוריד IS valid
chk("211.7",  "תורידי לרון גבינה 5% 40 גרם",                    name="רון",   food="גבינ",    grams="40",  reduce=True)  # תורידי IS valid
chk("211.8",  "תפחיתי לדני שמן זית 15 גרם",                     name="דני",   food="שמן זית", grams="15",  reduce=True)  # תפחיתי IS valid
chk("211.9",  "ורידי לליצקו קינואה 70 גרם",                     name="ליצקו", food="קינו",    grams="70")   # ורידי≠הורידי → no reduce
chk("211.10", "כנס לרון ירקות 200 גרם",                         name="רון",   food="ירק",     grams="200")  # כנס≠הכנס

# ═══════════════════════════════════════════════════════════════════════
# קבוצה 212: שכחת אות אחרונה — food names
# ═══════════════════════════════════════════════════════════════════════
print("\n══ קב׳ 212: שכחת אות אחרונה food ══")
chk("212.1",  "הוסף לרון אור 80 גרם",                           name="רון",   grams="80")    # אור≠אורז — no food
chk("212.2",  "הוסף לדני פסט 90 גרם",                           name="דני",                  grams="90")   # פסט קצר מדי לא מזוהה
chk("212.3",  "הוסף לליצקו בטט 150 גרם",                        name="ליצקו",                grams="150")  # בטט קצר מדי
chk("212.4",  "הוסף לרון קואק 60 גרם",                          name="רון",                  grams="60")   # קואק לא מזוהה
chk("212.5",  "הוסף לדני טונ 100 גרם",                          name="דני",   food="טונ",    grams="100")  # טונ IS the prefix used
chk("212.6",  "הוסף לליצקו גבינ 40 גרם",                        name="ליצקו", food="גבינ",   grams="40")   # גבינ IS the prefix
chk("212.7",  "הוסף לרון קינו 70 גרם",                          name="רון",   food="קינו",   grams="70")   # קינו IS the prefix
chk("212.8",  "הוסף לדני שיבול 80 גרם",                         name="דני",                  grams="80")   # שיבול קצר מדי לא מזוהה
chk("212.9",  "הוסף לליצקו ירק 200 גרם",                        name="ליצקו", food="ירק",    grams="200")  # ירק IS the prefix
chk("212.10", "הוסף לרון קינו 70 גרם לערב",                     name="רון",   food="קינו",   grams="70",  meal="ערב")

