# ═══════════════════════════════════════════════════════════════════════
# קבוצה 276: הפחתה/הורדה noun forms + שתורידי/ותורידי prefix
# ═══════════════════════════════════════════════════════════════════════
print("\n══ קב׳ 276: הפחתה/הורדה + שתורידי/ותורידי ══")
chk("276.1",  "הפחתה של 150 גרם בטטה לרון",     name="רון",   food="בטט",    grams="150", reduce=True)
chk("276.2",  "הורדה של 100 גרם אורז לדני",      name="דני",   food="אורז",   grams="100", reduce=True)
chk("276.3",  "הפחתה 200 גרם פסטה למיכל",        name="מיכל",  food="פסט",    grams="200", reduce=True)
chk("276.4",  "הורדה 80 גרם חזה עוף לרון",       name="רון",   food="חזה",    grams="80",  reduce=True)
chk("276.5",  "שתורידי 50 גרם אורז לדני",         name="דני",   food="אורז",   grams="50",  reduce=True)
chk("276.6",  "ותורידי 80 גרם עוף למיכל",         name="מיכל",  food="עוף",    grams="80",  reduce=True)
chk("276.7",  "שתפחיתי 100 גרם פסטה לרון",        name="רון",   food="פסט",    grams="100", reduce=True)
chk("276.8",  "ותפחיתי 60 גרם גבינה לדני",        name="דני",   food="גבינ",   grams="60",  reduce=True)
chk("276.9",  "הפחתה של 120 גרם קינואה לליצקו",  name="ליצקו", food="קינו",   grams="120", reduce=True)
chk("276.10", "הורדה של 75 גרם שמן זית למיכל",   name="מיכל",  food="שמן",    grams="75",  reduce=True)


