# סיכום
# ═══════════════════════════════════════════════════════════════════════
total = PASS + FAIL
print(f"\n{'═'*60}")
print(f"📊 תוצאות לאחר {total} טסטים: ✅ {PASS} עברו | ❌ {FAIL} נכשלו")
if FAILS:
    print("\n🔍 כשלונות מפורטים:")
    for label, msg, errors, parsed in FAILS:
        print(f"\n  [{label}] ← '{msg[:70]}'")
        print(f"         שגיאות: {errors}")
        print(f"         parse: name={parsed.get('name')}, change={parsed.get('change')!r}, meal={parsed.get('meal')}")
